    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    drows={i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg}
    dcols={j for j in range(w) if len({g[ii][j] for ii in range(h)})==1 and g[0][j]!=bg}
    def bands(d,n):
        bs=[];s=0
        for x in sorted(d): bs.append((s,x)); s=x+1
        if s<n: bs.append((s,n))
        return bs
    rbands=bands(drows,h); cbands=bands(dcols,w)
    pat=None
    for (r0,r1) in rbands:
        for (c0,c1) in cbands:
            if any(g[i][j]!=bg for i in range(r0,r1) for j in range(c0,c1)):
